PAT = re.compile(r'(?<![\w.])([ijklmnopqr]0)\.([A-Za-z0-9_]+)(?!\s*\()')


def sub(m):
    c, f = m.group(1), m.group(2)
    n = MAP.get(c, {}).get(f)
    return ('R.' + n) if n else m.group(0)


